using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "StarRequirementEffectAction", menuName = "Data/Battle/Battle Actions/Orion/StarRequirementEffect Action")]
public class StarRequirementEffectAction : DefaultEffectAction
{
	[Header("Star Requirement")]
	[SerializeField]
	private StarRequirementAction starRequirementAction;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		return starRequirementAction.CheckConditionToBeCasted(actionValue);
	}
}
